.c-animate-on-scroll-demo {
  --animate-on-scroll-accent: #b9f474;
  --animate-on-scroll-accent-text: #162600;
  --animate-on-scroll-border: #dcddd4;
  --animate-on-scroll-border-strong: #bfc1b7;
  --animate-on-scroll-canvas: #f5f5ef;
  --animate-on-scroll-focus: #b9f474;
  --animate-on-scroll-font: Inter, ui-sans-serif, system-ui, sans-serif;
  --animate-on-scroll-muted: #62665d;
  --animate-on-scroll-radius: 0.75rem;
  --animate-on-scroll-surface: #ffffff;
  --animate-on-scroll-text: #171915;

  align-content: start;
  background: var(--animate-on-scroll-canvas);
  color: var(--animate-on-scroll-text);
  display: grid;
  font-family: var(--animate-on-scroll-font);
  gap: 1rem;
  min-height: 100%;
  padding: 2rem;
}

.c-animate-on-scroll__header,
.c-animate-on-scroll__viewport {
  inline-size: min(100%, 42rem);
  margin-inline: auto;
}

.c-animate-on-scroll__header {
  display: grid;
  gap: 0.5rem;
}

.c-animate-on-scroll__eyebrow {
  color: var(--animate-on-scroll-muted);
  font-size: 0.7rem;
  font-weight: 650;
  letter-spacing: 0.08em;
  margin: 0;
  text-transform: uppercase;
}

.c-animate-on-scroll__header h2,
.c-animate-on-scroll__card h3 {
  letter-spacing: -0.04em;
  line-height: 1.05;
  margin: 0;
}

.c-animate-on-scroll__header h2 {
  font-size: clamp(1.55rem, 5vw, 2rem);
}

.c-animate-on-scroll__header > p:last-child,
.c-animate-on-scroll__card p:last-child {
  color: var(--animate-on-scroll-muted);
  line-height: 1.6;
  margin: 0;
}

.c-animate-on-scroll__viewport {
  background: var(--animate-on-scroll-surface);
  border: 1px solid var(--animate-on-scroll-border);
  border-radius: var(--animate-on-scroll-radius);
  display: grid;
  gap: 1rem;
  max-block-size: 20rem;
  overflow: auto;
  padding: 1rem;
  scroll-behavior: smooth;
  scroll-padding: 1rem;
}

.c-animate-on-scroll__viewport:focus-visible {
  outline: 0.2rem solid var(--animate-on-scroll-focus);
  outline-offset: 0.15rem;
}

.c-animate-on-scroll__card {
  border: 1px solid var(--animate-on-scroll-border);
  border-radius: var(--animate-on-scroll-radius);
  display: grid;
  gap: 0.5rem;
  padding: 1.5rem;
  opacity: 0;
  transform: translateY(1rem);
  transition: opacity 180ms ease, transform 180ms cubic-bezier(0.2, 0, 0, 1);
}

.c-animate-on-scroll__card.is-visible {
  opacity: 1;
  transform: none;
}

.c-animate-on-scroll-demo :focus-visible {
  outline: 0.2rem solid var(--animate-on-scroll-focus);
  outline-offset: 0.15rem;
}

@media (max-width: 32rem) {
  .c-animate-on-scroll-demo {
    padding: 1rem;
  }

  .c-animate-on-scroll__card {
    padding: 1rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .c-animate-on-scroll__viewport {
    scroll-behavior: auto;
  }

  .c-animate-on-scroll__card,
  .c-animate-on-scroll__card.is-visible {
    opacity: 1;
    transform: none;
    transition: none;
  }
}

